// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IAsset} from "../interfaces/IAsset.sol";
import {ISubAccounts} from "../interfaces/ISubAccounts.sol";

/**
 * @title ArrayDeltaLib
 * @author Lyra
 * @notice util functions for AssetDeltaLib operations
 */
library AssetDeltaLib {
  /// @dev too many deltas
  error DL_DeltasTooLong();

  /**
   * @notice apply delta to the AssetDeltaArrayCache.deltas array.
   * @dev if this is an asset never seen before, add to the accountDelta.deltas array
   *      if this is an asset seen before, update the accountDelta.deltas entry
   * @dev will revert if the delta array is already full (100 entries);
   *
   */
  function addToAssetDeltaArray(ISubAccounts.AssetDeltaArrayCache memory cache, ISubAccounts.AssetDelta memory delta)
    internal
    pure
  {
    for (uint i; i < cache.deltas.length;) {
      if (cache.deltas[i].asset == delta.asset && cache.deltas[i].subId == delta.subId) {
        cache.deltas[i].delta += delta.delta;
        return;
      } else if (cache.deltas[i].asset == IAsset(address(0)) && cache.deltas[i].subId == 0) {
        // find the first empty element, write information
        cache.deltas[i] = delta;
        unchecked {
          cache.used += 1;
        }
        return;
      }

      unchecked {
        i++;
      }
    }
    revert DL_DeltasTooLong();
  }

  function getDeltasFromArrayCache(ISubAccounts.AssetDeltaArrayCache memory cache)
    internal
    pure
    returns (ISubAccounts.AssetDelta[] memory)
  {
    ISubAccounts.AssetDelta[] memory deltas = new ISubAccounts.AssetDelta[](cache.used);
    for (uint i; i < deltas.length;) {
      deltas[i] = cache.deltas[i];

      unchecked {
        i++;
      }
    }
    return deltas;
  }

  function getDeltasFromSingleAdjustment(IAsset asset, uint subId, int delta)
    internal
    pure
    returns (ISubAccounts.AssetDelta[] memory)
  {
    ISubAccounts.AssetDelta[] memory deltas = new ISubAccounts.AssetDelta[](1);
    deltas[0] = ISubAccounts.AssetDelta({asset: asset, subId: uint96(subId), delta: delta});
    return deltas;
  }
}

src/libraries/PermitAllowanceLib.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IAllowances} from "../interfaces/IAllowances.sol";

/**
 * @title PermitAllowanceLib
 * @author Lyra
 * @notice hash function for PermitAllowance object
 */
library PermitAllowanceLib {
  bytes32 public constant PERMIT_ALLOWANCE_TYPEHASH = keccak256(
    "PermitAllowance(address delegate,uint256 nonce,uint256 accountId,uint256 deadline,AssetAllowance[] assetAllowances,SubIdAllowance[] subIdAllowances)AssetAllowance(address asset,uint256 positive,uint256 negative)SubIdAllowance(address asset,uint256 subId,uint256 positive,uint256 negative)"
  );

  bytes32 public constant ASSET_ALLOWANCE_TYPEHASH =
    keccak256("AssetAllowance(address asset,uint256 positive,uint256 negative)");

  bytes32 public constant SUBID_ALLOWANCE_TYPEHASH =
    keccak256("SubIdAllowance(address asset,uint256 subId,uint256 positive,uint256 negative)");

  /**
   * @dev hash the permit struct
   *      this function only hash the permit struct, needs to be combined with domain seperator to prevent replay attack
   *      and also to be compliant to EIP712 standard
   * @param permit permit struct to be hashed
   */
  function hash(IAllowances.PermitAllowance memory permit) internal pure returns (bytes32) {
    uint assetPermits = permit.assetAllowances.length;
    uint subIdPermits = permit.subIdAllowances.length;

    bytes32[] memory assetAllowancesHashes = new bytes32[](assetPermits);
    for (uint i = 0; i < assetPermits; ++i) {
      assetAllowancesHashes[i] = _hashAssetAllowance(permit.assetAllowances[i]);
    }

    bytes32[] memory subIdAllowancesHashes = new bytes32[](subIdPermits);
    for (uint i = 0; i < subIdPermits; ++i) {
      subIdAllowancesHashes[i] = _hashSubIdAllowance(permit.subIdAllowances[i]);
    }

    return keccak256(
      abi.encode(
        PERMIT_ALLOWANCE_TYPEHASH,
        permit.delegate,
        permit.nonce,
        permit.accountId,
        permit.deadline,
        keccak256(abi.encodePacked(assetAllowancesHashes)),
        keccak256(abi.encodePacked(subIdAllowancesHashes))
      )
    );
  }

  function _hashAssetAllowance(IAllowances.AssetAllowance memory allowance) private pure returns (bytes32) {
    return keccak256(abi.encode(ASSET_ALLOWANCE_TYPEHASH, allowance));
  }

  function _hashSubIdAllowance(IAllowances.SubIdAllowance memory allowance) private pure returns (bytes32) {
    return keccak256(abi.encode(SUBID_ALLOWANCE_TYPEHASH, allowance));
  }
}
